#!/usr/bin/env node
/**
 * Fails when an EAS build profile would install dependencies with a different
 * Node (and so a different npm) than the one the repo's lockfile is written by.
 *
 * EAS ignores the root .nvmrc and uses its build image's default Node unless
 * eas.json pins one. After the lockfile was regenerated by npm 11, EAS's
 * default Node 22 / npm 10 rejected it in `npm ci` ("Missing: utf-8-validate
 * from lock file"), and every EAS build broke while CI, which only queues EAS
 * with --no-wait, stayed green.
 *
 * Checks:
 * - every build profile in eas.json sets `node`, equal to .nvmrc's version;
 * - .nvmrc's major equals the major of the Node running this script (CI's).
 *
 * `extends` is not resolved: a profile must set its own `node`.
 *
 * Usage: node scripts/check-eas-node-version.mjs [path/to/eas.json] [path/to/.nvmrc]
 */
import { readFileSync } from "node:fs"
import path from "node:path"
import { fileURLToPath } from "node:url"

const appDir = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..")
const easJsonPath = path.resolve(process.argv[2] ?? path.join(appDir, "eas.json"))
const nvmrcPath = path.resolve(
  process.argv[3] ?? path.join(appDir, "..", "..", ".nvmrc"),
)

const major = (version) => version.split(".")[0]

const nvmrc = readFileSync(nvmrcPath, "utf8").trim().replace(/^v/, "")
const runningNode = process.versions.node
const problems = []

if (major(nvmrc) !== major(runningNode)) {
  problems.push(
    `.nvmrc pins Node ${nvmrc} but this runs on Node ${runningNode}; move .nvmrc, eas.json and CI's node-version together`,
  )
}

const profiles = JSON.parse(readFileSync(easJsonPath, "utf8")).build ?? {}
if (Object.keys(profiles).length === 0) {
  problems.push("eas.json has no build profiles")
}
for (const [name, profile] of Object.entries(profiles)) {
  const node = profile.node
  if (typeof node !== "string") {
    problems.push(`build profile "${name}" does not pin "node" (EAS would use its image default)`)
  } else if (node.replace(/^v/, "") !== nvmrc) {
    problems.push(`build profile "${name}" pins node ${node}, but .nvmrc is ${nvmrc}`)
  }
}

if (problems.length > 0) {
  for (const problem of problems) console.error(`check-eas-node-version: ${problem}`)
  process.exit(1)
}
console.log(
  `check-eas-node-version: ${Object.keys(profiles).length} EAS build profiles pin Node ${nvmrc}`,
)
